update:
set -euo pipefail; v=$(jq -er .flutter "{versions}"); fvm install "$v"; for dir in . tier; do printf '{
	"flutter": "%s"
}
' "$v" > "$dir/.fvmrc"; (cd "$dir" && fvm flutter pub get); done; jq --tab --arg version "$v" '.version = $version' arena.json > arena.json.tmp && mv arena.json.tmp arena.json
